1	import fs from 'node:fs';
2	import path from 'node:path';
3	import { spawnSync } from 'node:child_process';
4	const [label, exe, ...args] = process.argv.slice(2);
5	if (!/^[a-z][a-z0-9-]*$/.test(label ?? '') || !exe) throw Error('capture <unique label> <exe> <args...>');
6	const dir = path.resolve('acceptance/20261018-governance-a/commands', label);
7	fs.mkdirSync(dir, { recursive: true });
8	if (fs.existsSync(path.join(dir, 'result.json'))) throw Error('Never overwrite evidence');
9	const started = Date.now();
10	const isNpm = exe === 'npm.cmd';
11	if (isNpm && args.some(x => !/^[A-Za-z0-9:_-]+$/.test(x))) throw Error('Only simple npm script arguments are supported');
12	const actualExe = isNpm ? process.env.ComSpec : exe, actualArgs = isNpm ? ['/d', '/c', 'npm.cmd', ...args] : args;
13	const r = spawnSync(actualExe, actualArgs, { cwd: process.cwd(), windowsHide: true, timeout: 300000, maxBuffer: 100 * 1024 * 1024 });
14	fs.writeFileSync(path.join(dir, 'stdout.raw.txt'), r.stdout ?? Buffer.alloc(0));
15	fs.writeFileSync(path.join(dir, 'stderr.raw.txt'), r.stderr ?? Buffer.alloc(0));
16	const result = { exe, argv: args, actual_exe: actualExe, actual_argv: actualArgs, cwd: process.cwd(), started_at: new Date(started).toISOString(), elapsed_ms: Date.now() - started,
17	  exit_code: r.status, signal: r.signal, error: r.error?.message };
18	fs.writeFileSync(path.join(dir, 'result.json'), JSON.stringify(result, null, 2) + '\n', { flag: 'wx' });
19	if (r.stdout?.length) process.stdout.write(r.stdout);
20	if (r.stderr?.length) process.stderr.write(r.stderr);
21	console.log(JSON.stringify(result)); process.exitCode = r.status ?? 1;
